module OLED_ShowData_TH(
	sys_clk,
	rst_n,
	data_done,
	tempH,
	tempL,
	humidityH,
	humidityL,
	fontdata,
	show_THdata_req,
	write_done,
	show_THdata,
	show_THdata_finish,
	font_row,
	font,
	font_index_after);

	//---Ports declearation: generated by Robei---
	input sys_clk;
	input rst_n;
	input data_done;
	input [7:0] tempH;
	input [7:0] tempL;
	input [7:0] humidityH;
	input [7:0] humidityL;
	input [7:0] fontdata;
	input show_THdata_req;
	input write_done;
	output [23:0] show_THdata;
	output show_THdata_finish;
	output font_row;
	output [4:0] font;
	output [3:0] font_index_after;

	wire sys_clk;
	wire rst_n;
	wire data_done;
	wire [7:0] tempH;
	wire [7:0] tempL;
	wire [7:0] humidityH;
	wire [7:0] humidityL;
	wire [7:0] fontdata;
	wire show_THdata_req;
	wire write_done;
	wire [23:0] show_THdata;
	wire show_THdata_finish;
	reg font_row;
	reg [4:0] font;
	wire [3:0] font_index_after;

	//----Code starts here: integrated by Robei-----
	reg[7:0]		tempHREG;
	reg[7:0]		tempLREG;
	reg[7:0]		humidityHREG;
	reg[7:0]		humidityLREG;
	reg[3:0] 		font_index;
	reg[4:0]		font_sel;
	reg[7:0]		show_x;
	reg[3:0]		show_y;
	reg[23:0]		showfont_data_reg;
	
	wire				onefont_finish;
	assign onefont_finish  = (((font_row == 1'b1) &&( font_index == 5'd10 ))&& (write_done == 1'b1) )? 1'b1 : 1'b0;
	assign show_THdata_finish = (onefont_finish == 1'b1 && font_sel == 5'd7) ? 1'b1 : 1'b0;
	assign show_THdata = showfont_data_reg;
	assign font_index_after=font_index-2'd3;
	always@(*)
	begin
		case(font_index)
		'd0:	showfont_data_reg <= {8'h78,8'h00,8'hB0 + show_y + font_row};
		'd1:  showfont_data_reg <= {8'h78,8'h00,8'h00 + show_x[3:0]};
		'd2:  showfont_data_reg <= {8'h78,8'h00,8'h10 + show_x[7:4]};
		default:	showfont_data_reg <= {8'h78,8'h40,fontdata}; //fontdata
		endcase
	end
	
	always@(posedge sys_clk or negedge rst_n)
	begin
		if(rst_n == 1'b0)
			font_index <= 'd0;
		else if(write_done == 1'b1 && font_index == 'd10)
			font_index <= 'd0;
		else if(write_done == 1'b1 && show_THdata_req == 1'b1)
			font_index <= font_index + 1'b1;
		else
			font_index <= font_index;
	end
	
	always@(posedge sys_clk or negedge rst_n)
	begin
		if(rst_n == 1'b0)
			font_row <= 1'b0;
		else if(onefont_finish == 1'b1)
			font_row <= 1'b0;
		else if(write_done == 1'b1 && font_index == 5'd10)
			font_row <= 1'b1;
		else
			font_row <= font_row;
	end
	
	always@(posedge sys_clk or negedge rst_n)
	begin
		if(rst_n == 1'b0)
			font_sel <=5'd0;
		else if(show_THdata_finish == 1'b1)
			font_sel <= 5'd0;
		else if(onefont_finish == 1'b1)
			font_sel <= font_sel + 1'b1;
		else
			font_sel <= font_sel;
	end
	
	always@(posedge sys_clk or negedge rst_n)
	begin
		if(rst_n == 1'b0)
		begin
			show_x <= 'd0;
			show_y <= 'd0;
		end
		else if(font_sel == 5'd0)
		begin
			show_x <= 'd52;
			show_y <= 'd2;
		end
		else if(font_sel == 5'd1)
		begin
			show_x <= 'd60;
			show_y <= 'd2;
		end
		else if(font_sel == 5'd2)
		begin
			show_x <= 'd77;
			show_y <= 'd2;
		end
		else if(font_sel == 5'd3)
		begin
			show_x <= 'd86;
			show_y <= 'd2;
		end
		
		else if(font_sel == 5'd4)
		begin
			show_x <= 'd52;
			show_y <= 'd4;
		end
		else if(font_sel == 5'd5)
		begin
			show_x <= 'd60;
			show_y <= 'd4;
		end
		else if(font_sel ==5'd6)
		begin
			show_x <= 'd77;
			show_y <= 'd4;
		end
		else if(font_sel ==5'd7)
		begin
			show_x <= 'd86;
			show_y <= 'd4;
		end
		
		else
		begin
			show_x <= 'd0;
			show_y <= 'd0;
		end
	end
	
	always@(posedge sys_clk or negedge rst_n)
	begin
		if(rst_n == 1'b0)
			font <= 'd0;
		else if(font_sel == 5'd0)
			font <= tempHREG / 10;
		else if(font_sel == 5'd1)
			font <= tempHREG % 10;
		else if(font_sel == 5'd2)
			font <= tempLREG / 10;
		else if(font_sel == 5'd3)
			font <= tempLREG % 10;
			
		else if(font_sel == 5'd4)
			font <= humidityHREG / 10;
		else if(font_sel == 5'd5)
			font <= humidityHREG % 10;
		else if(font_sel == 5'd6)
			font <= humidityLREG / 10;
		else if(font_sel == 5'd7)
			font <= humidityLREG % 10;
		else
			font <= font;		
	end
	
	always@(posedge sys_clk or negedge rst_n)
	begin
		if(rst_n == 1'b0)
			tempHREG <= 'd0;
		else if(data_done == 1'b1)
			tempHREG <= tempH;
		else
			tempHREG <= tempHREG;
	end
	
	always@(posedge sys_clk or negedge rst_n)
	begin
		if(rst_n == 1'b0)
			tempLREG <= 'd0;
		else if(data_done == 1'b1)
			tempLREG <= tempL;
		else
			tempLREG <= tempLREG;
	end
	
	always@(posedge sys_clk or negedge rst_n)
	begin
		if(rst_n == 1'b0)
			humidityHREG <= 'd0;
		else if(data_done == 1'b1)
			humidityHREG <= humidityH;
		else
			humidityHREG <= humidityHREG;
	end
	
	always@(posedge sys_clk or negedge rst_n)
	begin
		if(rst_n == 1'b0)
			humidityLREG <= 'd0;
		else if(data_done == 1'b1)
			humidityLREG <= humidityL;
		else
			humidityLREG <= humidityLREG;
	end
	
	
	
endmodule    //OLED_ShowData_TH

